import logging
import re
from time import sleep
from ta_attenuator.attenuator import Attenuator
from ta_attenuator.attenuator import ChangingAttenutionValueOfNotReservedPort
from ta_attenuator.utils.telnet import TelnetClient
from ta_attenuator.attenuator import ReadingAttenuationValueOfNonexistentRFPath
from ta_attenuator.attenuator import AttenuationValueIsOtherThanExpected


class JfwAttenuator(Attenuator):
    """Module to control JFW attenuator"""
    # pylint: disable=anomalous-backslash-in-string, bare-except, too-many-instance-attributes
    DB_REGEX = '(\d{1,})\s{0,}dB'

    def __init__(self, min_attenuation, max_attenuation, ip, port, mode='ports'):
        super(JfwAttenuator, self).__init__()
        self.ip = ip
        self.port = port
        self.min_attenuation = min_attenuation
        self.max_attenuation = max_attenuation
        self.telnet = TelnetClient()
        self.conn = None
        self.is_connected = False
        self.mode = mode
        self.mode_singular = self.mode[0:-1]

    def connect_attenuator_controller(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-path of that device
        """
        if not self.is_connected:
            self.telnet.connect(self.ip, self.port)
            self.is_connected = True
            logging.info('Connection to JFW attenuator established.')

    def disconnect_attenuator_controller(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if not self.used_ports:
            self.telnet.close_connection()
        else:
            logging.info("Did not disconnect controller, because ports {} are still used.".format(self.used_ports))

    def read_rf_paths_attenuation(self, rf_paths):
        """read attenuation value in db for the first rf_path"""
        return self._read_attenuation_value(str(rf_paths[0]))

    def _set_single_rf_path_decibel_attenuation(self, rf_path_address, attenuation_value_db, confirm=True):
        if not self.check_if_port_is_reserved(rf_path_address):
            raise ChangingAttenutionValueOfNotReservedPort("{} {} was not reserved on attenuator!"
                                                           "Please check if this RF path "
                                                           "belongs to your cell.".format(self.mode_singular, rf_path_address))
        attenuation_value_db = int(attenuation_value_db)
        rf_path_address = str(rf_path_address)
        cmd = self._prepare_set_command(attenuation_value_db, rf_path_address)
        self._write(cmd)
        try:
            self._make_sure_port_has_correct_value(rf_path_address, attenuation_value_db, confirm)
        except:
            sleep(0.5)
            self._write(cmd)
            self._make_sure_port_has_correct_value(rf_path_address, attenuation_value_db, confirm)
        logging.info('{} ID {} value successfuly set to {} dB.'.format(self.mode_singular, rf_path_address, attenuation_value_db))

    def _prepare_set_command(self, attenuation_value, rf_path_address):
        if self.mode == 'ports':
            cmd = "SA{} {}".format(rf_path_address, attenuation_value)
        else:
            cmd = "SB{} {}".format(rf_path_address, attenuation_value)
        return cmd

    def _write(self, cmd):
        self.telnet.write_command(cmd)
        logging.debug('Sending command to JFW attenuator: {}'.format(cmd))

    def get_max_decibel_attenuation(self):
        """
        Returns Maximal value of attenuation possible on this attenuator. For ex. 95 dB
        :return: float
        """
        return self.max_attenuation

    def get_min_decibel_attenuation(self):
        """
        Returns Minimal value of attenuation possible on this attenuator. For ex. 5 dB
        :return: float
        """
        return self.min_attenuation

    def _make_sure_port_has_correct_value(self, port_id, value_desired, confirm):
        if confirm:
            value_read = self._read_attenuation_value(port_id)
            if int(value_read) != int(value_desired):
                raise AttenuationValueIsOtherThanExpected('Desired {} id {} value {} not set on attenuator! '
                                                          'Output from RA / RB {} = {}'.format(self.mode_singular, port_id, value_desired,
                                                                                               port_id, value_read))

    def _read_attenuation_value(self, port_id):
        output = ''
        value_read = None
        if self.mode == 'blocks':
            output = self.telnet.read_command("RB" + port_id)
        else:
            output = self.telnet.read_command("RA" + port_id)
        logging.debug(output)
        re_out = re.search(self.DB_REGEX, output)
        if re_out:
            logging.debug(re_out.groups()[0])
            value_read = re_out.groups()[0]
        elif 'does not exist' in output:
            raise ReadingAttenuationValueOfNonexistentRFPath("Tried to read attenuation of rf path {}."
                                                             "Such path does not exist".format(port_id))
        else:
            raise ValueError("Could not read attenuation value for {} {}.".format(port_id, self.mode_singular))
        return value_read
